public class Main {
    public static void main(String[] args) {
        String code = "PRIORITY";
        int days = switch (code) {
            case "LOW" -> 7;
            case "NORMAL" -> 4;
            case "PRIORITY" -> 2;
            default -> 5;
        };
        System.out.println(code + " ships in " + days + " days");
        System.out.println(days <= 2 ? "Fast track" : "Standard track");
    }
}

